import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider the polynomial P(x) = ∏_{k=1}^{ {num_factors} } (1 + (-1)^k ({linear_a}k + {linear_b})^{ {power_d} } x). Let C be the coefficient of x^{ {degree_t} } in the expansion of P(x). Find |C|.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters; retry until difficulty and validity constraints are met.
while True:
    num_factors = rng.randint(10, 18)
    linear_a = rng.choice([1, 2, 3])
    linear_b = rng.randint(0, 3)
    power_d = rng.choice([1, 2, 3])
    max_t = min(6, num_factors // 2)
    degree_t = rng.randint(3, max_t)
    # Compute the target coefficient via DP on elementary symmetric sums.
    dp = [0] * (degree_t + 1)
    dp[0] = 1
    for k in range(1, num_factors + 1):
        w = ((-1) ** k) * ((linear_a * k + linear_b) ** power_d)
        for j in range(degree_t, 0, -1):
            dp[j] += w * dp[j - 1]
    C = dp[degree_t]
    # Difficulty and validity guards: nontrivial magnitude, enough factors, no zero weights.
    if C == 0:
        continue
    if abs(C) < 1000:
        continue
    if num_factors < 2 * degree_t + 2:
        continue
    # Ensure no zero linear weights (though with chosen ranges this won't happen, we still guard).
    zero_weight = any((linear_a * k + linear_b) == 0 for k in range(1, num_factors + 1))
    if zero_weight:
        continue
    return {
        'num_factors': num_factors,
        'linear_a': linear_a,
        'linear_b': linear_b,
        'power_d': power_d,
        'degree_t': degree_t
    }

    def verifier(assign):
# Recompute, validate constraints, and return (True, answer) or (False, None).
# Extract and type-check.
try:
    n = int(assign['num_factors'])
    a = int(assign['linear_a'])
    b = int(assign['linear_b'])
    d = int(assign['power_d'])
    t = int(assign['degree_t'])
except Exception:
    # Missing or non-integer fields.
    return (False, None)
# Domain and difficulty checks.
if n < 8:
    # Too few factors to be challenging.
    return (False, None)
if t < 3:
    # Trivial degrees are disallowed.
    return (False, None)
if t > min(6, n // 2):
    # Degree out of allowed harder range.
    return (False, None)
if a not in (1, 2, 3):
    return (False, None)
if d not in (1, 2, 3):
    return (False, None)
if not isinstance(b, int) or b < 0 or b > 3:
    return (False, None)
if n < 2 * t + 2:
    # Ensure enough combinatorial complexity.
    return (False, None)
# Ensure no zero weights that collapse factors.
for k in range(1, n + 1):
    if a * k + b == 0:
        return (False, None)
# Compute coefficient via DP of elementary symmetric sums.
dp = [0] * (t + 1)
dp[0] = 1
for k in range(1, n + 1):
    w = ((-1) ** k) * ((a * k + b) ** d)
    for j in range(t, 0, -1):
        dp[j] += w * dp[j - 1]
C = dp[t]
if C == 0:
    # Avoid degenerate cancellations.
    return (False, None)
if abs(C) < 1000:
    # Enforce nontrivial magnitude for difficulty.
    return (False, None)
answer = abs(C)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

